import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-dialogos-padrao';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);


 const result=await evaluate(`(async()=>{
  const wait=ms=>new Promise(r=>setTimeout(r,ms)),canvas=phase.canvas,click=(pointerType='mouse')=>{const r=canvas.getBoundingClientRect();canvas.dispatchEvent(new PointerEvent('pointerdown',{pointerId:1,button:0,pointerType,isPrimary:true,clientX:r.left+r.width*.5,clientY:r.top+r.height*.5,bubbles:true,cancelable:true}));canvas.dispatchEvent(new PointerEvent('pointerup',{pointerId:1,pointerType,bubbles:true}));};
  const ctx=canvas.getContext('2d'),fill=ctx.fillText;let words=[];ctx.fillText=function(text,...args){words.push(String(text));return fill.call(ctx,text,...args);};
  try{
   game.startDebugPhase('bedroom','NORMAL');game.setPaused(false);await wait(4300);words=[];await wait(100);if(!words.some(t=>t.includes('Levanta')))throw Error('Fala inicial ausente');
   words=[];await wait(6000);if(!words.some(t=>t.includes('quarto era')))throw Error('Abertura não avançou automaticamente');words=[];click();await wait(120);if(!words.some(t=>t.includes('Cada coisa')))throw Error('Clique não passou narrador da abertura');
   for(let i=0;i<3;i++){click();await wait(100);}await wait(8600);
   Object.assign(game.state,{gameplayState:'GAMEPLAY_NORMAL',cutsceneActive:true,cutsceneStep:1,cutsceneTimer:0,isStandbyActive:false,plotTwistActive:false});await wait(100);click();await wait(80);if(game.state.cutsceneStep!==1||game.state.cutsceneTimer<210)throw Error('Narrador do castelo pulou também a fala de Nanda');click();await wait(80);if(game.state.cutsceneStep!==2)throw Error('Fala do castelo não avançou');click();await wait(80);
   Object.assign(game.state,{cutsceneActive:false,plotTwistActive:true,plotTwistStep:4,plotTwistTimer:0});await wait(100);click();await wait(80);if(game.state.plotTwistStep!==5)throw Error('Diálogo da menina não avançou');click();await wait(80);if(game.state.plotTwistTimer<210||!game.state.plotTwistActive)throw Error('Narrador da reviravolta pulou Nanda');click();await wait(80);
   game.startDebugPhase('toy-room','NORMAL');await wait(3450);const intro=game.toyRoomIntroduction;if(intro.stage.id!=='TR_004')throw Error('Cena da sala fora da fala esperada');click();await wait(100);if(intro.stage.id!=='TR_005')throw Error('Clique não adiantou personagem');click('touch');await wait(100);if(intro.stage.id!=='TR_006')throw Error('Toque não avançou narrador');click();await wait(100);if(intro.stage.time<3.9)throw Error('Não passou para segundo balão do narrador');click();await wait(100);if(intro.stage.id!=='TR_007')throw Error('Não passou para a fala de Nanda');click();await wait(3400);
   const room=game.state.toyRoomInstance.instance;room.introBannerTimer=0;room.story.state.returnDialogueElapsed=0;await wait(80);click();await wait(80);if(room.story.state.returnDialogueElapsed<90)throw Error('Retorno não adiantou a fala');
   game.startDebugPhase('garden','EASY');for(let i=0;i<200&&!game.state.toyRoomInstance.instance.garden.ready;i++)await wait(50);const garden=game.state.toyRoomInstance.instance.garden;await wait(5200);if(garden.state.story.openingIndex!==1)throw Error('Jardim não usa prazo original de cinco segundos');click('touch');await wait(100);if(garden.state.story.openingIndex!==2)throw Error('Toque não adiantou uma fala do jardim');
   return{aberturaAutomatica:true,casteloNarradorEPersonagens:true,reviravoltaNarradorEPersonagens:true,narradorPorClique:true,salaPersonagemNarradorToque:true,retornoDeBrinquedos:true,jardimAutomaticoEToque:true};
  }finally{ctx.fillText=fill;}
 })()`);
 await writeFile('docs/diario-ia/qa-resultados/yuna/dialogos-padrao.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
 const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/jardim.png',Buffer.from(shot.result.data,'base64'));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
